"""Heat diffusion on the GPU.

Usage: uv run python main.py GRID_FILE

GRID_FILE holds "<width> <height> <steps>" followed by height rows of width
integers. Each step replaces every cell with (4*self + left + right + up +
down) // 8, with out-of-grid neighbours clamped to the nearest inside cell.
The stencil runs as a compute shader; the grid is printed with a SUM line.
"""

import sys

import numpy as np
import wgpu

WORKGROUP = 8

STENCIL_SHADER = """
struct Params {
    width: u32,
    height: u32,
    pad0: u32,
    pad1: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8, 1)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= params.width || y >= params.height) {
        return;
    }

    let w = params.width;
    let left = select(x - 1u, 0u, x == 0u);
    let right = min(x + 1u, w - 1u);
    let up = select(y - 1u, 0u, y == 0u);
    let down = min(y + 1u, params.height - 1u);

    let centre = src[y * w + x];
    let sum = 4u * centre
        + src[y * w + left]
        + src[y * w + right]
        + src[up * w + x]
        + src[down * w + x];
    dst[y * w + x] = sum / 8u;
}
"""


def read_grid(path):
    with open(path) as f:
        tokens = f.read().split()
    width, height, steps = (int(t) for t in tokens[:3])
    cells = np.array([int(t) for t in tokens[3 : 3 + width * height]], dtype=np.uint32)
    if cells.size != width * height:
        sys.exit(f"{path}: expected {width * height} cells, found {cells.size}")
    return width, height, steps, cells


def diffuse(width, height, steps, cells):
    """Run `steps` stencil steps on the GPU and return the final cells as u32."""
    if steps == 0:
        return cells

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    storage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    size = cells.nbytes
    # Two buffers swapped each step, so every step reads only the previous state.
    buffers = [
        device.create_buffer_with_data(data=cells, usage=storage),
        device.create_buffer(size=size, usage=storage),
    ]
    params = device.create_buffer_with_data(
        data=np.array([width, height, 0, 0], dtype=np.uint32),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    module = device.create_shader_module(code=STENCIL_SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    layout = pipeline.get_bind_group_layout(0)
    bind_groups = [
        device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": params.size}},
                {"binding": 1, "resource": {"buffer": buffers[i], "offset": 0, "size": size}},
                {"binding": 2, "resource": {"buffer": buffers[1 - i], "offset": 0, "size": size}},
            ],
        )
        for i in (0, 1)
    ]

    groups_x = -(-width // WORKGROUP)
    groups_y = -(-height // WORKGROUP)
    encoder = device.create_command_encoder()
    for step in range(steps):
        cpass = encoder.begin_compute_pass()
        cpass.set_pipeline(pipeline)
        cpass.set_bind_group(0, bind_groups[step % 2])
        cpass.dispatch_workgroups(groups_x, groups_y, 1)
        cpass.end()
    device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(buffers[steps % 2])
    return np.frombuffer(data, dtype=np.uint32).copy()


def main():
    if len(sys.argv) != 2:
        sys.exit("usage: main.py GRID_FILE")

    width, height, steps, cells = read_grid(sys.argv[1])
    result = diffuse(width, height, steps, cells)

    rows = result.reshape(height, width).tolist()
    total = int(result.sum(dtype=np.uint64))
    lines = [" ".join(map(str, row)) for row in rows]
    lines.append(f"SUM {total}")
    sys.stdout.write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()

